import{_ as a,o as t,c as r,a2 as n}from"./chunks/framework.vLhlLNVn.js";const b=JSON.parse('{"title":"Wie hängen Adapter und ESPHome-Dashboard zusammen?","description":"","frontmatter":{"order":1,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/de/05.hintergrund/01.adapter-und-dashboard.md"},"headers":[],"relativePath":"de/adapter/esphome/hintergrund/adapter-und-dashboard.md","filePath":"de/adapter/esphome/hintergrund/adapter-und-dashboard.md","lastUpdated":null}'),d={name:"de/adapter/esphome/hintergrund/adapter-und-dashboard.md"};function s(i,e,o,h,u,m){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="wie-hangen-adapter-und-esphome-dashboard-zusammen" tabindex="-1">Wie hängen Adapter und ESPHome-Dashboard zusammen? <a class="header-anchor" href="#wie-hangen-adapter-und-esphome-dashboard-zusammen" aria-label="Permalink to &quot;Wie hängen Adapter und ESPHome-Dashboard zusammen?&quot;">​</a></h1><p><a id="use-esphome-home-assistant-run"></a></p><h2 id="kann-ich-esphome-ohne-home-assistant-nutzen-und-das-dashboard-im-adapter-betreiben" tabindex="-1">Kann ich ESPHome ohne Home Assistant nutzen und das Dashboard im Adapter betreiben? <a class="header-anchor" href="#kann-ich-esphome-ohne-home-assistant-nutzen-und-das-dashboard-im-adapter-betreiben" aria-label="Permalink to &quot;Kann ich ESPHome ohne Home Assistant nutzen und das Dashboard im Adapter betreiben?&quot;">​</a></h2><p>Ja. ESPHome braucht kein Home Assistant. Der Adapter steuert die Geräte über die Native API und kann auf Wunsch das ESPHome-Dashboard mitbringen, in dem du YAML-Dateien schreibst, kompilierst und flashst.</p><p>Das Dashboard schaltest du im Reiter „ESPHome-Dashboard“ mit „ESPHome-Dashboard aktivieren“ ein, standardmäßig ist es aus. Adapter und Dashboard arbeiten getrennt: Ein Gerät im Dashboard ist nicht automatisch im Adapter, und umgekehrt.</p><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/dashboard-einschalten#dashboard-tab-not-open-localhost">Dashboard-Tab öffnen</a> · <a href="#adapter-dashboard-show-device-status">Warum der Status abweicht</a></p><p><a id="adapter-dashboard-show-device-status"></a></p><h2 id="warum-zeigen-adapter-und-dashboard-den-geratestatus-unterschiedlich-an" tabindex="-1">Warum zeigen Adapter und Dashboard den Gerätestatus unterschiedlich an? <a class="header-anchor" href="#warum-zeigen-adapter-und-dashboard-den-geratestatus-unterschiedlich-an" aria-label="Permalink to &quot;Warum zeigen Adapter und Dashboard den Gerätestatus unterschiedlich an?&quot;">​</a></h2><p>Adapter und Dashboard prüfen den Gerätestatus unabhängig voneinander. Der Adapter zeigt, ob seine API-Verbindung zum Gerät steht (<code>info._online</code>). Das Dashboard prüft selbst, ob es das Gerät im Netz findet, und braucht dafür mDNS.</p><p>Darum kann ein Gerät im Adapter online und im Dashboard offline sein, vor allem wenn:</p><ul><li>das Gerät in einem anderen Netz oder VLAN liegt als der ioBroker-Rechner,</li><li>ioBroker in Docker ohne Host-Netzwerk läuft,</li><li>der Router mDNS-Namen nicht auflöst.</li></ul><p>Für die Steuerung aus ioBroker zählt nur der Status im Adapter. Ein Gerät, das nur im Adapter steht, holst du mit „Adopt“ oder einer neuen YAML ins Dashboard.</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/geraete-entdecken#devices-another-vlan-iobroker-runs">Geräte in anderem VLAN oder Docker</a></p>',13)])])}const c=a(d,[["render",s]]);export{b as __pageData,c as default};
